>\\n<li>Eventos Corporativos</li>\\n</ul>\\n<p>[divider height=\\\"30\\\"] [button title=\\\"Galeria de Eventos Realizados\\\" link=\\\"https://espacocoimbra.com.br/home-page/dresses/\\\" align=\\\"\\\" icon=\\\"\\\" icon_position=\\\"\\\" color=\\\"theme\\\" font_color=\\\"\\\" size=\\\"2\\\" full_width=\\\"\\\" class=\\\"\\\" download=\\\"\\\" rel=\\\"\\\" onclick=\\\"\\\"]</p>\",\"align\":\"\",\"align-mobile\":\"\",\"column_bg\":\"\",\"bg_image\":\"\",\"bg_position\":\"no-repeat;left top;;\",\"bg_size\":\"auto\",\"margin_bottom\":\"\",\"padding\":\"\",\"animate\":\"\",\"classes\":\"\",\"style\":\"\"}},{\"jsclass\":\"wrap\",\"uid\":\"w4os3kjvb\",\"attr\":{}},{\"jsclass\":\"section\",\"uid\":\"wlkgu2vm8\",\"attr\":{\"title\":\"\",\"bg_color\":\"\",\"bg_image\":\"\",\"bg_position\":\"no-repeat;left top;;\",\"bg_size\":\"auto\",\"bg_video_mp4\":\"\",\"bg_video_ogv\":\"\",\"padding_top\":\"50\",\"padding_bottom\":\"10\",\"divider\":\"\",\"decor_top\":\"\",\"decor_bottom\":\"\",\"navigation\":\"\",\"style\":\" equal-height-wrap\",\"class\":\"\",\"section_id\":\"\",\"visibility\":\"\",\"hide\":\"\",\"vb_postid\":\"64\",\"vb\":1,\"rwd\":\"desktop\"}},{\"jsclass\":\"column\",\"uid\":\"7993b3695\",\"attr\":{\"title\":\"Heading\",\"content\":\"<h2>O Espaço Coimbra, possui tudo para transformar o seu evento em um momento único.</h2>\",\"align\":\"center\",\"align-mobile\":\"\",\"column_bg\":\"\",\"bg_image\":\"\",\"bg_position\":\"no-repeat;left top;;\",\"bg_size\":\"auto\",\"margin_bottom\":\"\",\"padding\":\"\",\"animate\":\"\",\"classes\":\"\",\"style\":\"\"}},{\"jsclass\":\"wrap\",\"uid\":\"0746e3bd6\",\"attr\":{}},{\"jsclass\":\"image\",\"uid\":\"32b641c90\",\"attr\":{\"src\":\"https://espacocoimbra.com.br/home-page/wp-content/uploads/2024/08/teste2.fw_.png#126\",\"size\":\"\",\"width\":\"\",\"height\":\"\",\"align\":\"center\",\"stretch\":\"0\",\"border\":\"0\",\"margin\":\"\",\"margin_bottom\":\"\",\"link_image\":\"\",\"link\":\"\",\"target\":\"0\",\"hover\":\"\",\"al